const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/client\"\n}\n\n// ----------------------------------------------------\n// 1. MULTI-BRANCH SYSTEM (منظومة الفروع المتعددة)\n// ----------------------------------------------------\nmodel Branch {\n  id              String                   @id @default(cuid())\n  name            String // e.g. \"فرع حدائق القبة\", \"فرع مدينة نصر\"\n  code            String                   @unique // \"BR-KOBBA\", \"BR-NASR-CITY\"\n  address         String\n  phone           String\n  whatsapp        String?\n  googleMapsUrl   String?\n  isActive        Boolean                  @default(true)\n  createdAt       DateTime                 @default(now())\n  users           User[]\n  specialists     Specialist[]\n  bookings        Booking[]\n  tickets         Ticket[]\n  products        Product[]\n  ledgers         SpecialistLedger[]\n  offers          Offer[]\n  chatMessages    ChatMessage[]\n  shifts          CashShift[]\n  expenses        TreasuryExpense[]\n  attendances     AttendanceRecord[]\n  transfers       StockTransfer[]\n  consumptionLogs MaterialConsumptionLog[]\n  cameras         SecurityCamera[]\n  staffDossiers   StaffDossier[]\n}\n\n// ----------------------------------------------------\n// 2. STAFF & USERS RBAC (المستخدمين والصلاحيات)\n// ----------------------------------------------------\nmodel User {\n  id                String             @id @default(cuid())\n  name              String\n  username          String             @unique // maestro, hadayek-mgr, nasr-mgr, cashier1, etc.\n  passwordHash      String // 123456789\n  pin               String             @default(\"157230\") // PIN Code\n  phone             String?\n  role              String             @default(\"owner\") // owner, general_manager, manager, cashier, specialist, worker\n  branchId          String?\n  branch            Branch?            @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  permissions       String? // JSON array\n  isActive          Boolean            @default(true)\n  createdAt         DateTime           @default(now())\n  specialistProfile Specialist?\n  attendances       AttendanceRecord[]\n}\n\n// ----------------------------------------------------\n// 3. SPECIALISTS / BARBERS (المتخصصين وكراسي الحلاقة)\n// ----------------------------------------------------\nmodel Specialist {\n  id           String  @id @default(cuid())\n  userId       String? @unique\n  user         User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n  branchId     String\n  branch       Branch  @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  name         String\n  phone        String?\n  photo        String? // ImgBB URL\n  title        String  @default(\"خبير حلاقة وتصفيف\")\n  chairNumber  Int     @default(1)\n  status       String  @default(\"AVAILABLE\") // AVAILABLE, WITH_CLIENT, BREAK, OFF_DUTY, DAY_OFF, ABSENT\n  statusReason String? // سبب التعطيل أو الملاحظة (مثلاً: إجازة أسبوعية، استراحة غداء، انتهى اليوم ومشي)\n  rating       Float   @default(4.9)\n\n  // Compensation & Payroll scheme\n  payType        String @default(\"SALARY_PLUS_COMMISSION\") // DAILY, WEEKLY, MONTHLY, COMMISSION_ONLY, SALARY_PLUS_COMMISSION\n  baseSalary     Float  @default(0)\n  commissionRate Float  @default(20) // %\n\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  bookings Booking[]\n  tickets  Ticket[]\n  ledgers  SpecialistLedger[]\n}\n\n// ----------------------------------------------------\n// 4. DYNAMIC SERVICES CATALOG (الخدمات التجميلية والحلاقة)\n// ----------------------------------------------------\nmodel Service {\n  id              String   @id @default(cuid())\n  nameAr          String\n  nameEn          String?\n  category        String   @default(\"HAIR\") // HAIR, BEARD, SKIN_CARE, VIP_PACKAGES, KIDS, COLOR_KERATIN\n  price           Float\n  durationMinutes Int      @default(30)\n  description     String?\n  image           String? // ImgBB URL\n  sortOrder       Int      @default(0)\n  isActive        Boolean  @default(true)\n  createdAt       DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 5. CUSTOMER DATABASE & CRM (قاعدة بيانات العملاء والتسويق)\n// ----------------------------------------------------\nmodel Customer {\n  id               String    @id @default(cuid())\n  name             String\n  phone            String    @unique\n  email            String?\n  passwordHash     String?\n  isVerified       Boolean   @default(false)\n  verificationCode String?\n  avatar           String?\n  notes            String?\n  vipLevel         String    @default(\"REGULAR\") // REGULAR, VIP, GOLD_MEMBER\n  totalVisits      Int       @default(0)\n  totalSpent       Float     @default(0)\n  createdAt        DateTime  @default(now())\n  lastVisitAt      DateTime?\n\n  bookings Booking[]\n  tickets  Ticket[]\n}\n\n// ----------------------------------------------------\n// 6. APPOINTMENTS & BOOKINGS (الحجوزات المسبقة)\n// ----------------------------------------------------\nmodel Booking {\n  id                 String      @id @default(cuid())\n  bookingNumber      String      @unique // SAD-XXXX\n  customerId         String\n  customer           Customer    @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  branchId           String\n  branch             Branch      @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  specialistId       String?\n  specialist         Specialist? @relation(fields: [specialistId], references: [id], onDelete: SetNull)\n  serviceIds         String // JSON array: [{ id, nameAr, price, durationMinutes }]\n  bookingDate        String // YYYY-MM-DD\n  timeSlot           String // e.g. \"05:00 PM\"\n  status             String      @default(\"CONFIRMED\") // PENDING, CONFIRMED, IN_CHAIR, COMPLETED, CANCELLED, NO_SHOW\n  notes              String?\n  totalAmount        Float       @default(0)\n  reminderSentAt     DateTime?\n  overdueAlertSentAt DateTime?\n  createdAt          DateTime    @default(now())\n  updatedAt          DateTime    @updatedAt\n}\n\n// ----------------------------------------------------\n// 7. IN-CHAIR LIVE TICKETS (شاشة المتخصص والكرسي اللحظية)\n// ----------------------------------------------------\nmodel Ticket {\n  id            String     @id @default(cuid())\n  ticketNumber  String     @unique // CHAIR-XXXX\n  branchId      String\n  branch        Branch     @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  specialistId  String\n  specialist    Specialist @relation(fields: [specialistId], references: [id], onDelete: Cascade)\n  customerId    String?\n  customer      Customer?  @relation(fields: [customerId], references: [id], onDelete: SetNull)\n  customerName  String\n  customerPhone String?\n  chairNumber   Int        @default(1)\n  status        String     @default(\"IN_CHAIR\") // IN_CHAIR, READY_FOR_CASHIER, COMPLETED, CANCELLED\n\n  services    String @default(\"[]\") // JSON: [{ id, nameAr, price, addedAt }]\n  retailItems String @default(\"[]\") // JSON: [{ id, nameAr, price, qty, total }]\n\n  servicesTotal Float  @default(0)\n  retailTotal   Float  @default(0)\n  discount      Float  @default(0)\n  tipAmount     Float  @default(0)\n  finalAmount   Float  @default(0)\n  paymentMethod String @default(\"CASH\") // CASH, CARD, INSTAPAY, VODAFONE_CASH\n\n  startTime       DateTime  @default(now())\n  endTime         DateTime?\n  durationMinutes Int?\n\n  cashierName String?\n  notes       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 8. RETAIL & CONSUMABLE BEAUTY PRODUCTS (بضاعة التجميل وخامات التشغيل والمخزن)\n// ----------------------------------------------------\nmodel Product {\n  id                   String   @id @default(cuid())\n  branchId             String?\n  branch               Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  nameAr               String\n  category             String   @default(\"STYLING\") // STYLING, BEARD_CARE, SKIN_CARE, PERFUMES, ACCESSORIES, CONSUMABLES, LASER_SUPPLIES\n  price                Float // سعر البيع للجمهور (إذا كان RETAIL) أو قيمة الخدمة\n  costPrice            Float    @default(0) // تكلفة الشراء\n  stockQty             Int      @default(50) // رصيد الفرع الحالي\n  minStockAlert        Int      @default(10) // حد الطلب والتنبيه\n  image                String? // ImgBB URL\n  barcode              String? // باركود فريد دائم (سواء مولد تلقائي أو دولي)\n  barcodeType          String   @default(\"AUTO\") // AUTO (مولد تلقائي مميز DKN-XXXXXX), EXISTING (باركود المصنع)\n  usageType            String   @default(\"RETAIL\") // RETAIL (بضاعة بيع للعملاء), CONSUMABLE (خامات استهلاك وتشغيل)\n  unit                 String   @default(\"PIECE\") // PIECE (قطعة/شفرة/فوطة), BOTTLE (عبوة), GRAM (جرام), ML (مل), BOX (علبة)\n  centralStockQty      Int      @default(0) // رصيد المخزن الرئيسي العام\n  consumptionRule      String? // JSON rule: e.g. {\"type\":\"PER_SERVICE\",\"serviceCategory\":\"BEARD\",\"qty\":1}\n  estimatedUsesPerUnit Int      @default(1) // عدد مرات الاستخدام الافتراضية لكل عبوة\n  currentOpenedUnits   Int      @default(0) // عدد العبوات المفتوحة قيد الاستهلاك في محطات العمل\n  isActive             Boolean  @default(true)\n  createdAt            DateTime @default(now())\n  updatedAt            DateTime @default(now()) @updatedAt\n\n  purchases       StockPurchase[]\n  transfers       StockTransfer[]\n  consumptionLogs MaterialConsumptionLog[]\n}\n\n// ----------------------------------------------------\n// 9. SPECIALIST LEDGER & PAYROLL (سجل حسابات وسلف وأجور المتخصصين)\n// ----------------------------------------------------\nmodel SpecialistLedger {\n  id           String     @id @default(cuid())\n  specialistId String\n  specialist   Specialist @relation(fields: [specialistId], references: [id], onDelete: Cascade)\n  branchId     String\n  branch       Branch     @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  type         String // SALARY_PAYOUT, COMMISSION_EARNED, ADVANCE_WITHDRAWAL, BONUS, DEDUCTION\n  amount       Float\n  notes        String?\n  date         DateTime   @default(now())\n  recordedBy   String     @default(\"المالك (Maestro)\")\n  createdAt    DateTime   @default(now())\n}\n\n// ----------------------------------------------------\n// 10. SYSTEM GLOBAL SETTINGS & KILL SWITCH (إعدادات النظام والتحكم)\n// ----------------------------------------------------\nmodel SystemSettings {\n  id               String  @id @default(\"default-settings\")\n  salonNameAr      String  @default(\"مجموعة صالونات وسبا الباشا VIP\")\n  salonNameEn      String  @default(\"EL BASHA LUXURY SALON & SPA\")\n  logoUrl          String  @default(\"/dakn-logo.jpg\")\n  systemLocked     Boolean @default(false)\n  lockMessage      String  @default(\"النظام مغلق مؤقتاً لأعمال الصيانة والتحديث.\")\n  hadayekPhone     String  @default(\"01210103025\")\n  nasrCityPhone    String  @default(\"01556782015\")\n  hotline          String  @default(\"01210103025\")\n  whatsappNumber   String  @default(\"01210103025\")\n  facebookUrl      String  @default(\"https://www.facebook.com/DaknElbashaSalon\")\n  instagramUrl     String?\n  defaultOpenHour  String  @default(\"11:00 AM\")\n  defaultCloseHour String  @default(\"01:00 AM\")\n\n  // Weekly Day Off & Booking Policies\n  weeklyDayOff          String  @default(\"MONDAY\") // MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY, SATURDAY, SUNDAY, NONE\n  isDayOffEnabled       Boolean @default(true)\n  dayOffMessage         String  @default(\"عفواً، صالونات وسبا الباشا في عطلة أسبوعية يوم الإثنين - نتشرف بحجز موعدكم طوال باقي أيام الأسبوع ✂️\")\n  bookingSlotInterval   Int     @default(30) // in minutes\n  reminderMinutesBefore Int     @default(15) // reminder 15 min before\n  receiptFooterNotes    String  @default(\"شكراً لزيارتكم مجموعة صالونات وسبا الباشا VIP 👑 تجربة ملوكية استثنائية\")\n\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 11. DYNAMIC ROYAL OFFERS & PACKAGES (العروض الملكية والباكدجات)\n// ----------------------------------------------------\nmodel Offer {\n  id              String   @id @default(cuid())\n  titleAr         String // e.g. \"عرض العريس الملكي\"\n  badge           String? // \"خصم 46%\", \"VIP\", \"لفترة محدودة\"\n  price           Float // 3500\n  oldPrice        Float? // 4000\n  discountPercent Int? // 15\n  image           String // \"/offers/offer-groom-3500.jpg\"\n  description     String?\n  features        String   @default(\"[]\") // JSON array of bullet points\n  branchId        String? // null = متاح في كل الفروع\n  branch          Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  isActive        Boolean  @default(true)\n  sortOrder       Int      @default(0)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 12. IN-APP LIVE CHAT (شات مباشر وتواصل فوري بين الصالون والعملاء)\n// ----------------------------------------------------\nmodel ChatMessage {\n  id            String   @id @default(cuid())\n  branchId      String?\n  branch        Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  customerId    String?\n  customerName  String   @default(\"عميل VIP\")\n  customerPhone String?\n  bookingId     String?\n  sender        String // \"CUSTOMER\" or \"SALON\"\n  senderName    String   @default(\"خدمة عملاء مجموعة الباشا VIP\")\n  message       String\n  isRead        Boolean  @default(false)\n  createdAt     DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 13. CASH SHIFTS & DRAWER CLOSING (إقفال الورديات وتسليم النقدية)\n// ----------------------------------------------------\nmodel CashShift {\n  id          String    @id @default(cuid())\n  shiftNumber String    @unique // SHIFT-XXXX\n  branchId    String\n  branch      Branch    @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  cashierName String\n  openedAt    DateTime  @default(now())\n  closedAt    DateTime?\n  status      String    @default(\"OPEN\") // OPEN, CLOSED\n\n  // Financial breakdown\n  ticketsCount      Int   @default(0)\n  servicesTotal     Float @default(0) // إجمالي الحلاقة\n  retailTotal       Float @default(0) // إجمالي مبيعات المنتجات\n  cashCollected     Float @default(0) // نقدية كاش مقبوضة\n  visaCollected     Float @default(0) // فيزا وماستر\n  instapayCollected Float @default(0) // انستاباي\n  vodafoneCollected Float @default(0) // فودافون كاش\n\n  advancesPayouts Float @default(0) // سلف ومستحقات خرجت نقداً\n  expensesTotal   Float @default(0) // مصروفات ونثريات خرجت نقداً\n\n  expectedCash Float @default(0) // النقدية الصافية المطلوبة بالدرج\n  actualCash   Float @default(0) // النقدية الفعلية المسلمة\n  difference   Float @default(0) // عجز أو زيادة (+/-)\n\n  handedTo String  @default(\"المالك (Maestro)\") // تم تسليم الفلوس لمين\n  notes    String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 14. GENERAL TREASURY EXPENSES (مصروفات ونثريات الخزينة)\n// ----------------------------------------------------\nmodel TreasuryExpense {\n  id            String   @id @default(cuid())\n  branchId      String?\n  branch        Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  category      String // SUPPLIES, UTILITIES, RENT, REFRESHMENTS, MAINTENANCE, OTHER\n  amount        Float\n  paymentMethod String   @default(\"CASH\") // CASH, CARD, INSTAPAY, VODAFONE_CASH\n  description   String\n  recipientName String? // اسم المستلم / المورد\n  recordedBy    String   @default(\"الكاشير\")\n  date          DateTime @default(now())\n  createdAt     DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 15. DIGITAL ATTENDANCE & PUNCH (بصمة الحضور والانصراف الرقمية)\n// ----------------------------------------------------\nmodel AttendanceRecord {\n  id           String    @id @default(cuid())\n  userId       String\n  user         User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  branchId     String\n  branch       Branch    @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  date         String // YYYY-MM-DD\n  checkInTime  DateTime  @default(now())\n  checkOutTime DateTime?\n  status       String    @default(\"PRESENT\") // PRESENT, LATE, LEFT_EARLY, COMPLETED\n  notes        String?\n  ipAddress    String?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n}\n\n// ----------------------------------------------------\n// 16. CENTRAL WAREHOUSE: PURCHASES & OPENING INVENTORY (المشتريات وجرد أول المدة)\n// ----------------------------------------------------\nmodel StockPurchase {\n  id            String   @id @default(cuid())\n  invoiceNumber String // e.g. \"PUR-2026-001\" or \"OPEN-BAL-001\"\n  type          String   @default(\"PURCHASE\") // \"PURCHASE\" (فاتورة شراء), \"OPENING_BALANCE\" (جرد رصيد أول المدة)\n  supplierName  String? // اسم المورد أو الشركة\n  productId     String\n  product       Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  quantity      Int // الكمية المضافة\n  costPrice     Float // سعر الشراء للوحدة\n  totalCost     Float // الإجمالي\n  destination   String   @default(\"CENTRAL\") // \"CENTRAL\" (المخزن الرئيسي) أو معرف فرع محدد\n  notes         String?\n  recordedBy    String   @default(\"مسئول المخزن\")\n  createdAt     DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 17. CENTRAL WAREHOUSE: TRANSFERS & DISPATCH (التحويلات وصرف الفروع)\n// ----------------------------------------------------\nmodel StockTransfer {\n  id             String   @id @default(cuid())\n  transferNumber String // e.g. \"TRF-2026-001\"\n  productId      String\n  product        Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  fromLocation   String   @default(\"المخزن الرئيسي\")\n  toBranchId     String\n  toBranch       Branch   @relation(fields: [toBranchId], references: [id], onDelete: Cascade)\n  quantity       Int // الكمية المحولة\n  status         String   @default(\"COMPLETED\") // PENDING, COMPLETED, CANCELLED\n  receivedBy     String? // اسم مستلم الفرع (الكاشير أو المدير)\n  dispatchedBy   String   @default(\"مسئول المخزن العام\")\n  notes          String?\n  createdAt      DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 18. CONSUMABLES DEPLETION LOG (سجل الاستهلاك الذكي للخامات)\n// ----------------------------------------------------\nmodel MaterialConsumptionLog {\n  id               String   @id @default(cuid())\n  productId        String\n  product          Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  branchId         String\n  branch           Branch   @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  ticketId         String? // معرف الفاتورة/التذكرة إن وجد\n  specialistId     String? // معرف المتخصص/الحلاق إن وجد\n  serviceName      String? // اسم الخدمة المرتبطة (مثل: حلاقة ذقن بالبخار)\n  quantityConsumed Float // الكمية المستهلكة (مثلاً: 1 شفرة، أو 0.04 عبوة = 15 مل)\n  unit             String   @default(\"PIECE\") // PIECE, BOTTLE, ML, GRAM\n  reason           String   @default(\"AUTO_SERVICE_RULE\") // AUTO_SERVICE_RULE, MANUAL_STATION_HANDOVER, WASTAGE\n  date             String // YYYY-MM-DD\n  notes            String?\n  createdAt        DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 19. CCTV SECURITY SURVEILLANCE (منظومة كاميرات المراقبة الحية VIP)\n// ----------------------------------------------------\nmodel SecurityCamera {\n  id                  String   @id @default(cuid())\n  name                String // اسم الكاميرا، مثلاً: \"كاميرا 1: صالة كراسي الحلاقة الكبرى\"\n  branchId            String? // الفرع التابعة له أو null للإدارة العامة / الخزنة\n  branch              Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  venueType           String   @default(\"DAKN\") // \"DAKN\" (رجالي), \"HAMMAM\" (حريمي), \"NEWSKIN\" (عيادة), \"TREASURY\" (خزنة وكاشير), \"OFFICE\" (مكتب)\n  locationDescription String // e.g. \"صالة الحلاقة الكبرى - 6 كراسي\"\n  feedType            String   @default(\"SIMULATION\") // \"STREAM\" (HLS/WebRTC), \"SNAPSHOT\" (MJPEG/HTTP Refresh), \"IFRAME\" (Cloud P2P / Web Portal), \"SIMULATION\" (Real-time VIP Surveillance Simulation)\n  feedUrl             String? // e.g. Stream m3u8 or iframe URL\n  snapshotUrl         String? // e.g. HTTP snapshot image URL\n  rtspUrl             String? // e.g. rtsp://admin:pass@192.168.1.108:554/cam/realmonitor...\n  ipAddress           String? // IP or DDNS (e.g. 192.168.1.108)\n  port                Int?     @default(80)\n  channelNumber       Int      @default(1)\n  streamQuality       String   @default(\"2K\") // 4K, 2K, 1080P, 720P\n  fps                 Int      @default(30)\n  hasNightVision      Boolean  @default(true)\n  hasPTZ              Boolean  @default(true)\n  hasAudio            Boolean  @default(false)\n  isActive            Boolean  @default(true)\n  sortOrder           Int      @default(1)\n  notes               String?\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 20. STAFF DOSSIER & HR ARCHIVE (أرشيف شؤون العاملين والمستندات)\n// ----------------------------------------------------\nmodel StaffDossier {\n  id             String  @id @default(cuid())\n  fullName       String // الاسم الرباعي\n  nationalId     String? // الرقم القومي (14 رقم)\n  phone          String\n  phoneSecondary String? // رقم طوارئ\n  birthDate      String? // YYYY-MM-DD\n  address        String? // العنوان ومحل الإقامة\n  gender         String  @default(\"MALE\") // MALE, FEMALE\n  maritalStatus  String? // أعزب، متزوج، يعول\n  militaryStatus String? // معفي، أدى الخدمة، غير مطلوب\n  qualification  String? // المؤهل الدراسي\n  jobTitle       String // المسمى الوظيفي\n  department     String  @default(\"DAKN\") // DAKN, HAMMAM, NEWSKIN, MANAGEMENT, GENERAL\n  branchId       String?\n  branch         Branch? @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  hireDate       String? // YYYY-MM-DD\n  status         String  @default(\"ACTIVE\") // ACTIVE, ON_LEAVE, ARCHIVED, TERMINATED\n  salary         Float   @default(0)\n  commissionRate Float   @default(0)\n  contractType   String  @default(\"FULL_TIME\") // FULL_TIME, PART_TIME, PERCENTAGE\n\n  // Official Documents (روابط المستندات والصور)\n  photoUrl          String? // الصورة الشخصية\n  nationalIdFront   String? // صورة البطاقة وجه\n  nationalIdBack    String? // صورة البطاقة ظهر\n  certificates      String? // JSON Array: [{ title: string, url: string }]\n  healthCertUrl     String? // الشهادة الصحية\n  healthCertExpiry  String? // تاريخ انتهاء الشهادة الصحية\n  criminalRecordUrl String? // الفيش الجنائي\n  contractDocUrl    String? // صورة عقد العمل\n  additionalDocs    String? // JSON Array: [{ title: string, url: string }]\n\n  notes        String? // ملاحظات وتقييمات الإدارة\n  userId       String? // رابط مع حساب الدخول بالسيستم\n  specialistId String? // رابط مع ملف المتخصص\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 21. JOB APPLICATIONS (بوابة طلبات التوظيف والتقديم الإلكتروني)\n// ----------------------------------------------------\nmodel JobApplication {\n  id                 String  @id @default(cuid())\n  code               String  @unique // APP-XXXXXX\n  fullName           String // الاسم الرباعي\n  phone              String\n  nationalId         String? // الرقم القومي\n  age                Int?\n  address            String? // المنطقة / المحافظة\n  targetJob          String // الوظيفة المتقدم لها\n  targetDepartment   String  @default(\"ALL\") // DAKN, HAMMAM, NEWSKIN, ALL\n  targetBranchId     String?\n  experienceYears    Int     @default(0)\n  previousWorkplaces String? // الأماكن السابقة\n  qualification      String? // المؤهل الدراسي\n  expectedSalary     Float?\n  personalPhoto      String? // صورة المتقدم\n  nationalIdUrl      String? // صورة البطاقة\n  cvUrl              String? // السيرة الذاتية أو الشهادات\n  portfolioUrls      String? // JSON Array\n  notes              String? // رسالة المتقدم\n\n  status         String   @default(\"PENDING\") // PENDING, REVIEWING, INTERVIEWED, ACCEPTED, REJECTED, ARCHIVED\n  interviewDate  String? // موعد المقابلة\n  interviewNotes String? // تقييم المقابلة\n  dossierId      String? // معرّف ملف الموظف في حال القبول والتعيين\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n}\n"
}

